INSERT INTO chldrn_symptms
	(
		SYMPTMS_NO
		, SYMPTMS_BGNDT
		, SYMPTMS_ENDDT
		, SYMPTMS_MEMO
		, ATCH_CODE
		, CHLDRN_NO
		, SYMPTMS_TY
		, SYMPTMS_VISITDT
	)
VALUES
	(
		#{symptmsNo}
		, #{symptmsBgndt}
		, #{symptmsEnddt}
		, #{symptmsMemo}
		, #{atchCode}
		, #{chldrnNo}
		, #{symptmsTy}
		, #{symptmsVisitdt}
	)

