		, TAKNG_MDCIN_TY
		, TAKNG_MDCIN_AMT
		, TAKNG_MDCIN_UNIT
		, TAKNG_PD
		, TAKNG_MEMO
	)
VALUES
	(
		#{chldrnNo}
